/// df stub state: [freeMbFirst] is served on every `df` call until the
/// call counter advances past [freeSwitchAfterCall], then [freeMbSecond].
late final Directory stubBin;
late final Directory stubState;

void writeDfStub({
  required int freeMbFirst,
  required int freeMbSecond,
  int freeSwitchAfterCall = 1,
}) {
  stubState
    ..deleteSync(recursive: true)
    ..createSync();
  File('${stubState.path}/free-first').writeAsStringSync('$freeMbFirst');
  File('${stubState.path}/free-second').writeAsStringSync('$freeMbSecond');
  File('${stubState.path}/switch-after').writeAsStringSync('$freeSwitchAfterCall');
  File('${stubBin.path}/df').writeAsStringSync('''
#!/usr/bin/env bash
# gh-2152 fixture seam: deterministic df -Pm output for every path; the
# free-MB value flips after N calls (the preflight re-checks AFTER the
# reclaim — the flip simulates the reclaimed bytes).
count_file="\$FAH_DF_STUB_STATE/calls"
n=\$(cat "\$count_file" 2>/dev/null || echo 0); n=\$((n+1)); echo "\$n" > "\$count_file"
switch=\$(cat "\$FAH_DF_STUB_STATE/switch-after")
if [ "\$n" -gt "\$switch" ]; then
  free=\$(cat "\$FAH_DF_STUB_STATE/free-second")
else
  free=\$(cat "\$FAH_DF_STUB_STATE/free-first")
fi
echo "Filesystem 1024-blocks Used Available Capacity Mounted-on"
echo "/dev/disk3s1 1000000 900000 \$free 90% /System/Volumes/Data"
''')
    ..setPermissionsSync(const [0x111, 0x124, 0x1ed][2]);
}

/// Backdate a path (or symlink itself, never its target) by [days].
void backdate(String path, {double days = 3}) {
  final r = Process.runSync('python3', [
    '-c',
    'import os, sys, time; t = time.time() - $days * 86400; '
        'os.utime(sys.argv[1], (t, t), follow_symlinks=False)',
    path,
  ]);
  expect(r.exitCode, 0, reason: r.stderr);
}

({int code, String out}) runPreflight(List<String> args) {
